//! Property tests for the invariants P1-P9 of docs/11 §10.
//!
//! Inputs are generated by exhaustive enumeration over small, structured
//! domains (every DACL of up to two ACEs over an ACE alphabet; every
//! combination of subject, action, attribute, context, policy and PIP
//! configuration listed below). Deterministic — no random generator, no
//! external crate. Source: docs/11 §10 (the invariants), §4 (the layers);
//! hand-made domains; no vector from another implementation.

mod common;

use common::*;
use dtyp::{Ace, Guid, SecurityDescriptor, Sid};
use pdp::access_check::rights::*;
use pdp::{
    acl_grants, decide, is_write, mandatory_fast_rules, AccessRequest, Action, ActionClass,
    ActionMatch, AnonymousGrant, AttrClass, AttrId, AuthMatch, AuthStrength, ContextMatch,
    ControlRightId, Decision, DirObjectContext, Dn, Effect, Instant, IpScope, Match, ObjClass,
    Obligation, PolicySnapshot, PolicyVersion, ReasonCode, Resource, ResourceMatch, Right, Rule,
    RuleError, RuleId, Subject, SubjectMatch, SubtreeBase, Tier, TimeWindow, TransportSec,
};

// ------------------------------------------------------------ domains ----

/// The ACE alphabet: simple / object ACEs (attribute, property set, control
/// right), allow / deny, two trustees, three masks, with and without
/// INHERIT_ONLY_ACE.
fn ace_alphabet() -> Vec<Ace> {
    let mut out = Vec::new();
    let masks = [
        RIGHT_DS_READ_PROPERTY,
        RIGHT_DS_READ_PROPERTY | RIGHT_DS_WRITE_PROPERTY,
        RIGHT_GENERIC_ALL,
    ];
    for sid in [user(), other_user()] {
        for mask in masks {
            let aces = [
                allow(mask, sid),
                deny(mask, sid),
                allow_obj(mask, Some(attr_in_set()), sid),
                deny_obj(mask, Some(attr_in_set()), sid),
                allow_obj(mask, Some(propset()), sid),
                deny_obj(mask, Some(propset()), sid),
                allow_obj(mask, Some(right_a()), sid),
            ];
            for ace in aces {
                out.push(inherit_only(ace.clone()));
                out.push(ace);
            }
        }
    }
    out
}

/// Every DACL of length 0, 1 or 2 over the alphabet.
fn all_dacls() -> Vec<Vec<Ace>> {
    let alphabet = ace_alphabet();
    let mut out = vec![vec![]];
    for a in &alphabet {
        out.push(vec![a.clone()]);
    }
    for a in &alphabet {
        for b in &alphabet {
            out.push(vec![a.clone(), b.clone()]);
        }
    }
    out
}

/// A smaller set of descriptors for the `decide`-level properties: no DACL,
/// empty DACL, grant-all, deny-all, an unsupported ACE, and a few mixes.
fn some_descriptors() -> Vec<SecurityDescriptor> {
    vec![
        sd_without_dacl(None),
        sd(None, vec![]),
        sd(Some(user()), vec![]),
        sd(None, vec![allow(RIGHT_GENERIC_ALL, group())]),
        sd(
            None,
            vec![
                deny(RIGHT_GENERIC_ALL, user()),
                allow(RIGHT_GENERIC_ALL, user()),
            ],
        ),
        sd(
            None,
            vec![
                unsupported(dtyp::ace_type::ACCESS_ALLOWED_CALLBACK_ACE_TYPE),
                allow(RIGHT_GENERIC_ALL, group()),
            ],
        ),
        sd(
            None,
            vec![
                allow_obj(RIGHT_DS_READ_PROPERTY, Some(propset()), group()),
                allow_obj(RIGHT_DS_CONTROL_ACCESS, Some(right_a()), user()),
            ],
        ),
        sd(None, vec![allow(RIGHT_GENERIC_READ, group())]),
    ]
}

fn every_right() -> Vec<Right> {
    vec![
        Right::Object {
            mask: RIGHT_DS_READ_PROPERTY,
        },
        Right::Object {
            mask: RIGHT_READ_CONTROL | RIGHT_WRITE_DAC,
        },
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(plain_set()),
            attribute: attr_in_set(),
        },
        Right::Property {
            mask: RIGHT_DS_WRITE_PROPERTY,
            property_set: None,
            attribute: attr_alone(),
        },
        Right::CreateChild {
            class: class_group(),
        },
        Right::ControlAccess { right: right_a() },
    ]
}

fn subjects() -> Vec<Subject> {
    let mut out = Vec::new();
    for groups in [vec![], vec![group()]] {
        for tier in [Tier::Tier0, Tier::Tier1] {
            for (strength, verified) in [
                (AuthStrength::Kerberos, true),
                (AuthStrength::Unauth, false),
                (AuthStrength::Pkinit, false),
            ] {
                let mut s = subject(user(), &groups, tier);
                s.auth.strength = strength;
                s.auth.ticket_verified = verified;
                out.push(s);
            }
        }
    }
    out
}

fn dir_actions() -> Vec<(Action, Option<dtyp::Guid>)> {
    vec![
        (Action::DirRead, None),
        (Action::DirRead, Some(attr_in_set())),
        (Action::DirRead, Some(attr_alone())),
        (Action::DirWrite, None),
        (Action::DirWrite, Some(attr_alone())),
        (Action::DirList, None),
        (Action::DirDelete, None),
        (Action::DirAddChild(ObjClass(class_group())), None),
        (Action::DirControlRight(ControlRightId(right_a())), None),
        // Malformed: a whole-object action with an attribute.
        (Action::DirList, Some(attr_alone())),
    ]
}

fn transports() -> Vec<TransportSec> {
    vec![
        TransportSec::NONE,
        TransportSec {
            encrypted: true,
            sealed: false,
            channel_bound: false,
        },
        TransportSec {
            encrypted: true,
            sealed: true,
            channel_bound: true,
        },
    ]
}

fn policies() -> Vec<PolicySnapshot> {
    let deny_group = Rule {
        id: RuleId(2),
        effect: Effect::Deny,
        when: Match {
            subject: SubjectMatch::MemberOf(group()),
            ..match_all()
        },
        obligations: vec![Obligation::Audit],
    };
    let allow_reads = Rule {
        id: RuleId(3),
        effect: Effect::Allow,
        when: Match {
            action: ActionMatch::AnyOf(vec![Action::DirRead, Action::DirList]),
            resource: subtree(parent_dn()),
            ..match_all()
        },
        obligations: vec![Obligation::Audit],
    };
    vec![
        policy(vec![]),
        policy(vec![allow_everything(1)]),
        policy(vec![allow_everything(1), deny_group]),
        policy(vec![allow_reads]),
    ]
}

/// Visit every generated `decide` input. `f` gets the request, the policy
/// and the PIP.
fn for_each_decide_input(mut f: impl FnMut(&AccessRequest, &PolicySnapshot, &MockPip)) {
    let attr_classes = [
        AttrClass::Normal,
        AttrClass::Sensitive {
            control_access_right: ControlRightId(right_a()),
        },
        AttrClass::Secret,
    ];
    let pols = policies();
    for descriptor in some_descriptors() {
        for object_tier in [Tier::Tier0, Tier::Tier1] {
            for class in attr_classes {
                for pip_tier in [Tier::Tier0, Tier::Tier1] {
                    let mut pip = MockPip::with_sd(descriptor.clone());
                    pip.object_tiers.insert(obj_dn(), object_tier);
                    pip.attr_classes.insert(AttrId(attr_alone()), class);
                    pip.attr_classes.insert(AttrId(attr_in_set()), class);
                    pip.tiers.insert(user(), pip_tier);
                    for s in subjects() {
                        for (action, attr) in dir_actions() {
                            for sec in transports() {
                                let mut req = dir_request(s.clone(), action.clone(), attr);
                                req.context.transport_sec = sec;
                                for pol in &pols {
                                    f(&req, pol, &pip);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fn object() -> DirObjectContext {
    DirObjectContext {
        object_class: class_user(),
        superclasses: vec![],
        object_sid: Some(user()),
    }
}

// ----------------------------------------------------------- P1, P7 ----

/// P1 (decide is total and deterministic: same input, same answer, never a
/// panic) and P7 (every decision carries exactly one Audit obligation), plus
/// the shape of a decision: Allow ⇔ reason `Allowed`.
#[test]
fn p1_p7_decide_is_total_deterministic_and_audited() {
    let mut count = 0usize;
    let mut reasons = std::collections::BTreeMap::<ReasonCode, usize>::new();
    for_each_decide_input(|req, pol, pip| {
        let first = decide(req, pol, pip);
        let second = decide(req, pol, pip);
        assert_eq!(first, second, "P1: not deterministic for {req:?}");
        assert!(exactly_one_audit(&first), "P7: {first:?}");
        assert_eq!(
            first.effect == Effect::Allow,
            first.reason == ReasonCode::Allowed,
            "decision shape: {first:?}"
        );
        *reasons.entry(first.reason).or_default() += 1;
        count += 1;
    });
    assert!(count > 100_000, "domain too small: {count}");
    // The domain reaches every layer: each of these outcomes occurs.
    for reason in [
        ReasonCode::Allowed,
        ReasonCode::InvalidRequest,
        ReasonCode::Unauthenticated,
        ReasonCode::WeakTransport,
        ReasonCode::SubjectMismatch,
        ReasonCode::CoarseDeny(RuleId(2)),
        ReasonCode::NoGrant,
        ReasonCode::TierViolation,
        ReasonCode::Acl,
        ReasonCode::NoSuchPath,
        ReasonCode::Sensitive,
    ] {
        assert!(
            reasons.get(&reason).copied().unwrap_or(0) > 0,
            "outcome never reached: {reason:?} ({reasons:?})"
        );
    }
}

/// P1 for the ACL check alone: `acl_grants` is total and deterministic over
/// every DACL of up to two ACEs, every owner and every kind of right.
#[test]
fn p1_acl_grants_is_total_and_deterministic() {
    let s = the_user();
    let o = object();
    for aces in all_dacls() {
        for owner in [None, Some(user()), Some(other_user())] {
            let d = sd(owner, aces.clone());
            for right in every_right() {
                assert_eq!(
                    acl_grants(&s, &d, &o, &right),
                    acl_grants(&s, &d, &o, &right)
                );
            }
        }
    }
}

// ---------------------------------------------------------------- P2 ----

/// P2 (deny by default): with no rules nothing is allowed; and nothing on a
/// directory object is allowed unless the ACL grants the desired right.
#[test]
fn p2_default_deny() {
    for_each_decide_input(|req, pol, pip| {
        let d = decide(req, pol, pip);
        if pol.rules().is_empty() {
            assert_eq!(d.effect, Effect::Deny, "P2: no rule, yet {d:?}");
        }
        if d.effect == Effect::Allow {
            // An Allow rule matched (layer 3)...
            assert!(
                pol.rules()
                    .iter()
                    .any(|r| r.effect == Effect::Allow && r.when.matches(req)),
                "P2: allowed without a matching Allow rule"
            );
            // ...and the descriptor has a DACL (rule 5a) with at least one ACE.
            let descriptor = pip.sds.get(&obj_dn()).expect("known object");
            assert!(
                descriptor.dacl.as_ref().is_some_and(|d| !d.aces.is_empty()),
                "P2: allowed through an absent or empty DACL: {req:?}"
            );
        }
    });
}

/// P2 for the ACL check: an empty DACL grants a non-owner nothing, and no
/// DACL (rule 5a) grants nothing to anyone.
#[test]
fn p2_acl_default_deny() {
    let o = object();
    for s in subjects() {
        for right in every_right() {
            assert!(!acl_grants(&s, &sd(Some(other_user()), vec![]), &o, &right));
            for owner in [None, Some(user()), Some(other_user())] {
                assert!(!acl_grants(&s, &sd_without_dacl(owner), &o, &right));
            }
        }
    }
}

// ---------------------------------------------------------------- P3 ----

/// P3 (no Subject field is client-claimed): whenever the request's tier
/// differs from the PIP's, the decision is Deny.
#[test]
fn p3_tier_not_claimable() {
    for_each_decide_input(|req, pol, pip| {
        let pip_tier = pip.tiers.get(&req.subject.principal).copied();
        if pip_tier != Some(req.subject.tier) {
            assert_eq!(decide(req, pol, pip).effect, Effect::Deny, "P3: {req:?}");
        }
    });
}

// ---------------------------------------------------------------- P4 ----

/// P4 (an explicit Deny at any layer ⇒ Deny), layer 3: adding a matching
/// Deny rule — first or last — to any policy makes every decision Deny.
#[test]
fn p4_explicit_deny_rule_wins() {
    let deny_all = Rule {
        id: RuleId(99),
        effect: Effect::Deny,
        when: match_all(),
        obligations: vec![],
    };
    for_each_decide_input(|req, pol, pip| {
        let mut first = vec![deny_all.clone()];
        first.extend(pol.rules().iter().cloned());
        let mut last: Vec<Rule> = pol.rules().to_vec();
        last.push(deny_all.clone());
        for rules in [first, last] {
            let d = decide(req, &policy(rules), pip);
            assert_eq!(d.effect, Effect::Deny, "P4: {req:?}");
        }
    });
}

/// P4, layer 5: a deny ACE for the requester's own SID at the head of any
/// DACL denies the requested right (owners drawn from {none, the requester,
/// someone else}, so no owner-implied right is left — [MS-DTYP] 2.5.3.2,
/// Q-050).
#[test]
fn p4_explicit_deny_ace_wins() {
    let s = the_user();
    let o = object();
    for aces in all_dacls() {
        for owner in [None, Some(user()), Some(other_user())] {
            for right in every_right() {
                let mask = match right {
                    Right::Object { mask } | Right::Property { mask, .. } => mask,
                    Right::CreateChild { .. } => RIGHT_DS_CREATE_CHILD,
                    Right::ControlAccess { .. } => RIGHT_DS_CONTROL_ACCESS,
                };
                let mut with_deny = vec![deny(mask, user())];
                with_deny.extend(aces.iter().cloned());
                assert!(
                    !acl_grants(&s, &sd(owner, with_deny), &o, &right),
                    "P4: {right:?} {aces:?}"
                );
            }
        }
    }
}

// ---------------------------------------------------------------- P5 ----

/// P5 (the tier invariant holds independently of the ACL): a write to a
/// Tier-0 object by a non-Tier-0 subject is denied for every descriptor —
/// including grant-all and absent-DACL ones — and every policy; when layers
/// 1-3 pass, the reason is the tier violation itself.
#[test]
fn p5_tier_invariant_independent_of_acl() {
    let mut descriptors = some_descriptors();
    for aces in all_dacls().into_iter().step_by(97) {
        descriptors.push(sd(None, aces));
    }
    for descriptor in descriptors {
        let mut pip = MockPip::with_sd(descriptor);
        pip.object_tiers.insert(obj_dn(), Tier::Tier0);
        for (action, attr) in dir_actions() {
            if !is_write(&action) {
                continue;
            }
            for pol in policies() {
                let req = dir_request(the_user(), action.clone(), attr);
                let d = decide(&req, &pol, &pip);
                assert_eq!(d.effect, Effect::Deny, "P5: {req:?}");
                // Under the Allow-all policy layers 1-3 pass (authenticated
                // Tier-1 subject, full transport), so layer 4 is what denies.
                if pol == policy(vec![allow_everything(1)]) {
                    assert_eq!(d.reason, ReasonCode::TierViolation, "P5: {req:?}");
                }
            }
        }
    }
}

// ---------------------------------------------------------------- P6 ----

/// P6 (a Secret attribute is unreachable): every request naming a Secret
/// attribute is denied, for every descriptor, subject, tier, transport and
/// policy.
#[test]
fn p6_secret_unreachable() {
    for_each_decide_input(|req, pol, pip| {
        if let pdp::Resource::DirObject { attr: Some(a), .. } = &req.resource {
            if pip.attr_classes.get(a) == Some(&AttrClass::Secret) {
                assert_eq!(decide(req, pol, pip).effect, Effect::Deny, "P6: {req:?}");
            }
        }
    });
}

// ---------------------------------------------------------------- P8 ----

/// P8 (deny-widening is visible within a bounded time; errors fail closed):
/// the core is stateless, so a policy or descriptor change that removes a
/// grant is effective on the very next call.
#[test]
fn p8_revocation_is_immediate() {
    let req = dir_request(the_user(), Action::DirRead, Some(attr_alone()));
    let granting = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_READ, user())]));
    let v1 = policy(vec![allow_everything(1)]);
    assert_eq!(decide(&req, &v1, &granting).effect, Effect::Allow);

    // Policy change: a Deny rule in the next snapshot.
    let mut rules = v1.rules().to_vec();
    rules.push(Rule {
        id: RuleId(5),
        effect: Effect::Deny,
        when: match_all(),
        obligations: vec![],
    });
    assert_eq!(decide(&req, &policy(rules), &granting).effect, Effect::Deny);

    // Directory change: the grant removed from the descriptor.
    let revoked = MockPip::with_sd(sd(None, vec![]));
    assert_eq!(decide(&req, &v1, &revoked).effect, Effect::Deny);

    // And back: nothing was remembered.
    assert_eq!(decide(&req, &v1, &granting).effect, Effect::Allow);
}

// ---------------------------------------------------------------- P9 ----

/// P9 (no dependence on clock non-determinism beyond the explicit
/// `Context.time`): without time-window rules, decisions do not depend on
/// `Context.time` at all; with one, they depend only on it.
#[test]
fn p9_no_clock_dependence() {
    let times = [Instant(0), Instant(1_700_000_000), Instant(u64::MAX)];
    for_each_decide_input(|req, pol, pip| {
        let reference = decide(req, pol, pip);
        for t in times {
            let mut at = req.clone();
            at.context.time = t;
            // A different ticket age does not matter either.
            at.subject.auth.ticket_age = core::time::Duration::from_secs(u64::from(t.0 as u32));
            assert_eq!(decide(&at, pol, pip), reference, "P9: {req:?}");
        }
    });

    // With a window: a function of Context.time only.
    let window = TimeWindow::new(Instant(100), Instant(200)).expect("ordered");
    let timed = policy(vec![Rule {
        id: RuleId(1),
        effect: Effect::Allow,
        when: Match {
            context: ContextMatch {
                time_window: Some(window),
                ..ContextMatch::ANY
            },
            ..match_all()
        },
        obligations: vec![],
    }]);
    let pip = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_READ, user())]));
    let mut req = dir_request(the_user(), Action::DirRead, Some(attr_alone()));
    let mut decisions: Vec<(u64, Decision)> = Vec::new();
    for t in [99u64, 100, 150, 200, 201] {
        req.context.time = Instant(t);
        decisions.push((t, decide(&req, &timed, &pip)));
    }
    for (t, d) in &decisions {
        let inside = (100..=200).contains(t);
        assert_eq!(d.effect == Effect::Allow, inside, "P9 window at {t}");
        req.context.time = Instant(*t);
        assert_eq!(&decide(&req, &timed, &pip), d);
    }
}

// ------------------------------------------------- A-28 never widens ----

/// The ACE alphabet of `a28_never_grants_more_than_before`: the base
/// alphabet plus allow / deny object ACEs naming each class of the chains
/// (most specific, superclass, a class in no chain is `class_group`, already
/// a child class) and both GUIDs of the shared property set.
fn a28_alphabet() -> Vec<Ace> {
    let mut out = ace_alphabet();
    let masks = [
        RIGHT_DS_READ_PROPERTY,
        RIGHT_DS_READ_PROPERTY | RIGHT_DS_WRITE_PROPERTY,
        RIGHT_GENERIC_ALL,
    ];
    for mask in masks {
        for g in [
            class_user(),
            class_computer(),
            class_top(),
            shared_guid(),
            attr_in_shared_set(),
        ] {
            for ace in [
                allow_obj(mask, Some(g), user()),
                deny_obj(mask, Some(g), user()),
            ] {
                out.push(inherit_only(ace.clone()));
                out.push(ace);
            }
        }
    }
    out
}

/// The objects: the default one (`class_user`, no other class listed) and a
/// `class_computer` with its superclass chain.
fn a28_objects() -> Vec<DirObjectContext> {
    vec![
        object(),
        DirObjectContext {
            object_class: class_computer(),
            superclasses: vec![class_top(), class_person(), class_user()],
            object_sid: Some(user()),
        },
    ]
}

/// Every right of `every_right()`, plus the requests A-28 is about: the
/// attribute whose GUID is its own property set's, another member of that
/// set, a child of the object's own class and a child of `class_user`
/// (a superclass of the computer; the object's own class for the user).
fn a28_rights(o: &DirObjectContext) -> Vec<Right> {
    let mut out = every_right();
    out.extend([
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(shared_set()),
            attribute: shared_guid(),
        },
        Right::Property {
            mask: RIGHT_DS_WRITE_PROPERTY,
            property_set: Some(shared_set()),
            attribute: shared_guid(),
        },
        Right::Property {
            mask: RIGHT_DS_READ_PROPERTY,
            property_set: Some(shared_set()),
            attribute: attr_in_shared_set(),
        },
        Right::CreateChild {
            class: o.object_class,
        },
        Right::CreateChild {
            class: class_user(),
        },
    ]);
    out
}

/// The request as the object type tree before A-28 saw it, so that
/// `acl_grants` on it gives the pre-A-28 result:
/// - the root was labelled by the most specific class only (the PIP gave
///   no other class): `superclasses` is emptied;
/// - nothing marked a property set GUID as an attribute's:
///   `is_attribute_guid` is cleared;
/// - every object ACE was located at the shallowest node carrying its GUID,
///   so a lower node with the same GUID as a higher one was never located
///   itself and was reached by exactly the ACEs that reached the higher
///   node. It behaved as the higher node (an attribute below its own
///   property set: the set node is dropped) or as a node no ACE names (a
///   child class equal to the object's class: replaced by `guid(0x7F)`,
///   outside every alphabet).
///
/// Checked once against the pre-change build over this test's domain
/// (459,382 cases with owner `None`): identical results.
fn pre_a28(o: &DirObjectContext, right: &Right) -> (DirObjectContext, Right) {
    let object = DirObjectContext {
        superclasses: Vec::new(),
        ..o.clone()
    };
    let unnamed = guid(0x7F);
    let right = match *right {
        Right::Property {
            mask,
            property_set: Some(set),
            attribute,
        } if set.guid == attribute => Right::Property {
            mask,
            property_set: None,
            attribute,
        },
        Right::Property {
            mask,
            property_set: Some(set),
            attribute,
        } => Right::Property {
            mask,
            property_set: Some(pdp::PropertySet {
                guid: set.guid,
                is_attribute_guid: false,
            }),
            attribute,
        },
        Right::CreateChild { class } if class == o.object_class => {
            Right::CreateChild { class: unnamed }
        }
        Right::ControlAccess { right } if right == o.object_class => {
            Right::ControlAccess { right: unnamed }
        }
        other => other,
    };
    (object, right)
}

/// A-28 (Q-081) item 3: neither rule ever grants more than the object type
/// tree without it. Over every DACL of up to two ACEs (base alphabet plus
/// class-typed and shared-GUID object ACEs), both objects, two owners and
/// every right: A-28 grants ⇒ the pre-A-28 tree grants. The domain also
/// reaches a strictly stricter result for each rule, so the check is not
/// vacuous. Source: A-28 (Q-081); [MS-ADTS] 5.1.3.3.3; the invariant stated
/// in `access_check`'s module documentation.
#[test]
fn a28_never_grants_more_than_before() {
    let s = the_user();
    let mut checked = 0usize;
    // Strictly stricter results: superclass (computer object), shared GUID
    // outside the chain (other member), shared GUID inside the chain (the
    // attribute itself), child of the object's own class.
    let (mut superclass, mut other_member, mut in_chain, mut own_child) = (0, 0, 0, 0);
    let alphabet = a28_alphabet();
    let mut dacls = vec![vec![]];
    dacls.extend(alphabet.iter().map(|a| vec![a.clone()]));
    for a in &alphabet {
        for b in &alphabet {
            dacls.push(vec![a.clone(), b.clone()]);
        }
    }
    for aces in &dacls {
        for owner in [None, Some(user())] {
            let d = sd(owner, aces.clone());
            for o in a28_objects() {
                for right in a28_rights(&o) {
                    let (old_object, old_right) = pre_a28(&o, &right);
                    let now = acl_grants(&s, &d, &o, &right);
                    let before = acl_grants(&s, &d, &old_object, &old_right);
                    assert!(
                        !now || before,
                        "A-28 widened a grant: {right:?} on {o:?} with {aces:?}, owner {owner:?}"
                    );
                    if before && !now {
                        // Attribute each stricter result to one rule: rule 1
                        // alone on the computer for the rights of
                        // `every_right()` (no duplicate GUID involved), rule
                        // 2 alone on the user object (no superclass listed).
                        let duplicate = match right {
                            Right::Property {
                                property_set: Some(set),
                                attribute,
                                ..
                            } if set.is_attribute_guid => Some(if set.guid == attribute {
                                &mut in_chain
                            } else {
                                &mut other_member
                            }),
                            Right::CreateChild { class } if class == o.object_class => {
                                Some(&mut own_child)
                            }
                            _ => None,
                        };
                        match (o.superclasses.is_empty(), duplicate) {
                            (true, Some(count)) => *count += 1,
                            (false, None) if every_right().contains(&right) => superclass += 1,
                            _ => {}
                        }
                    }
                    checked += 1;
                }
            }
        }
    }
    assert!(checked > 900_000, "domain too small: {checked}");
    for (rule, count) in [
        ("superclass deny", superclass),
        ("shared GUID, other member", other_member),
        ("shared GUID, the attribute", in_chain),
        ("child of the object's own class", own_child),
    ] {
        assert!(count > 0, "never stricter than before: {rule}");
    }
}

// ------------------------------------------------------- layer 2 table ----

/// Layer 2 follows `required_sec` exactly, for every action (A-22): with an
/// authenticated subject, an Allow-all policy and a transport with no
/// protection, the decision is `WeakTransport` if and only if the action has
/// a floor — so DnsUpdate and the Kdc* actions are never refused for their
/// transport, and every other action is.
#[test]
fn layer2_follows_required_sec_for_every_action() {
    use pdp::{KerbResKind, PolicyScope, Resource, ShareId, Spn, ZoneId};
    let dir = |attr: Option<dtyp::Guid>| Resource::DirObject {
        dn: obj_dn(),
        attr: attr.map(AttrId),
    };
    let dns = Resource::Dns {
        zone: ZoneId("test".into()),
        record: None,
    };
    let kerberos = Resource::Kerberos {
        kind: KerbResKind::Service(Spn("ldap/dc1.test".into())),
    };
    let file = Resource::File {
        share: ShareId("sysvol".into()),
        path: pdp::FilePath(vec!["a".into()]),
    };
    let cases = vec![
        (Action::DirRead, dir(Some(attr_alone()))),
        (Action::DirWrite, dir(Some(attr_alone()))),
        (Action::DirAddChild(ObjClass(class_group())), dir(None)),
        (Action::DirDelete, dir(None)),
        (Action::DirList, dir(None)),
        (
            Action::DirControlRight(ControlRightId(right_a())),
            dir(None),
        ),
        (
            Action::RpcCall,
            Resource::RpcMethod {
                iface: guid(0x66),
                opnum: 0,
            },
        ),
        (Action::FileRead, file.clone()),
        (Action::FileWrite, file),
        (Action::DnsUpdate, dns.clone()),
        (Action::DnsXfer, dns),
        (Action::KdcAs, kerberos.clone()),
        (Action::KdcTgs, kerberos.clone()),
        (Action::KdcS4u2Self, kerberos.clone()),
        (Action::KdcS4u2Proxy, kerberos),
        (
            Action::PolicyAdmin,
            Resource::Policy {
                scope: PolicyScope("domain".into()),
            },
        ),
    ];
    let pip = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_ALL, group())]));
    let pol = policy(vec![allow_everything(1)]);
    for (action, resource) in cases {
        let mut req = AccessRequest {
            subject: the_user(),
            resource,
            action: action.clone(),
            context: strong_context(),
        };
        req.context.transport_sec = TransportSec::NONE;
        let has_floor = pdp::required_sec(&action) != TransportSec::NONE;
        let d = decide(&req, &pol, &pip);
        assert_eq!(
            d.reason == ReasonCode::WeakTransport,
            has_floor,
            "{action:?}: {d:?}"
        );
        if !has_floor {
            assert_eq!(d.effect, Effect::Allow, "{action:?}: {d:?}");
        }
    }
}

// ------------------------------------- mandatory FAST: never widens ----
//
// Source: docs/48 §7.2 (`Match.auth`, option (i); `NotMemberOf`, option
// (ii)); Q-127 interim decision (P-10, (c) = (ii)); docs/11 §3 (rules;
// explicit Deny wins), §10 (P1, P2, P4, P7). Hand-made domains; no vector
// from another implementation.

/// The Kerberos policies of the equivalence domain: those of `policies()`
/// plus an Allow for every Kerberos action, the same with a Deny for one
/// group's TGS, and an Allow for AS of a TGT only. None names `auth` or a
/// negated subject — they are rules as written before either existed.
fn kerberos_policies() -> Vec<PolicySnapshot> {
    let allow_kerberos = Rule {
        id: RuleId(4),
        effect: Effect::Allow,
        when: Match {
            action: ActionMatch::Class(ActionClass::Kerberos),
            ..match_all()
        },
        obligations: vec![],
    };
    let deny_tgs_group = Rule {
        id: RuleId(5),
        effect: Effect::Deny,
        when: Match {
            action: ActionMatch::Exact(Action::KdcTgs),
            subject: SubjectMatch::MemberOf(group()),
            ..match_all()
        },
        obligations: vec![],
    };
    let allow_as_tgt = Rule {
        id: RuleId(6),
        effect: Effect::Allow,
        when: Match {
            action: ActionMatch::Exact(Action::KdcAs),
            resource: ResourceMatch::Kerberos {
                kind: Some(pdp::KerbResKind::Tgt),
            },
            ..match_all()
        },
        obligations: vec![],
    };
    let mut out = policies();
    out.push(policy(vec![allow_kerberos.clone()]));
    out.push(policy(vec![allow_kerberos, deny_tgs_group]));
    out.push(policy(vec![allow_as_tgt]));
    out
}

/// Every Kerberos action against a TGT and a service, plus one malformed
/// pair (an AS on a DNS zone).
fn kerberos_cases() -> Vec<(Action, pdp::Resource)> {
    use pdp::{KerbResKind, Resource, Spn, ZoneId};
    let tgt = Resource::Kerberos {
        kind: KerbResKind::Tgt,
    };
    let service = Resource::Kerberos {
        kind: KerbResKind::Service(Spn("host/a.test".into())),
    };
    let mut out = Vec::new();
    for action in [
        Action::KdcAs,
        Action::KdcTgs,
        Action::KdcS4u2Self,
        Action::KdcS4u2Proxy,
    ] {
        out.push((action.clone(), tgt.clone()));
        out.push((action, service.clone()));
    }
    out.push((
        Action::KdcAs,
        Resource::Dns {
            zone: ZoneId("test".into()),
            record: None,
        },
    ));
    out
}

/// Visit every Kerberos `decide` input: both PIP tiers, every subject of
/// `subjects()`, every pair of `kerberos_cases()`, every transport and every
/// policy of `kerberos_policies()`.
fn for_each_kerberos_input(mut f: impl FnMut(&AccessRequest, &PolicySnapshot, &MockPip)) {
    let pols = kerberos_policies();
    for pip_tier in [Tier::Tier0, Tier::Tier1] {
        let mut pip = MockPip::with_sd(sd(None, vec![]));
        pip.tiers.insert(user(), pip_tier);
        for s in subjects() {
            for (action, resource) in kerberos_cases() {
                for sec in transports() {
                    let req = AccessRequest {
                        subject: s.clone(),
                        resource: resource.clone(),
                        action: action.clone(),
                        context: pdp::Context {
                            transport_sec: sec,
                            transport: pdp::Transport::Kerberos,
                            ..strong_context()
                        },
                    };
                    for pol in &pols {
                        f(&req, pol, &pip);
                    }
                }
            }
        }
    }
}

/// Both equivalence domains: the directory inputs of `for_each_decide_input`
/// and the Kerberos inputs of `for_each_kerberos_input`.
fn for_each_equivalence_input(mut f: impl FnMut(&AccessRequest, &PolicySnapshot, &MockPip)) {
    for_each_decide_input(&mut f);
    for_each_kerberos_input(&mut f);
}

/// The size of the equivalence domain the one-time pre-change check covered.
const EQUIVALENCE_DOMAIN: usize = 142_776;

/// The same request with `armored` set as given.
fn with_armored(req: &AccessRequest, armored: bool) -> AccessRequest {
    let mut r = req.clone();
    r.subject.auth.armored = armored;
    r
}

/// Membership computed here, independently of `SubjectMatch`.
fn is_in(s: &Subject, sid: &Sid) -> bool {
    s.principal == *sid || s.groups.contains(sid)
}

/// Rules without `auth` behave exactly as before (Q-127 interim; docs/48
/// §7.2): over both domains (every input, `armored` true and false) the
/// decision does not depend on `armored`. `decide` never reads it, so only
/// a rule naming it could.
///
/// Checked once against the pre-change build (before `Match.auth` and
/// `NotMemberOf` existed) over exactly this domain: the decisions (effect,
/// reason, obligations) of all 142,776 inputs were identical to the
/// post-change decisions with `armored = true` and with `armored = false`.
#[test]
fn auth_free_policies_ignore_armored() {
    let mut count = 0usize;
    for_each_equivalence_input(|req, pol, pip| {
        let armored = decide(&with_armored(req, true), pol, pip);
        let unarmored = decide(&with_armored(req, false), pol, pip);
        assert_eq!(armored, unarmored, "{req:?}");
        count += 1;
    });
    assert_eq!(
        count, EQUIVALENCE_DOMAIN,
        "the domain the pre-change check covered changed"
    );
}

/// A rule whose `auth` is `AuthMatch::ANY` and whose subject is not negated
/// matches exactly the conjunction of the four matchers it had before
/// (docs/11 §3), and applies exactly when it matches, for either value of
/// `armored`: `eval_rules` sees every pre-existing rule as before.
#[test]
fn auth_any_rules_match_exactly_as_before() {
    let mut count = 0usize;
    for_each_equivalence_input(|req, pol, _pip| {
        for armored in [true, false] {
            let r = with_armored(req, armored);
            for rule in pol.rules() {
                assert_eq!(rule.when.auth, AuthMatch::ANY);
                assert!(!rule.when.subject.is_negated());
                let before = rule.when.action.matches(&r.action)
                    && rule.when.resource.matches(&r.resource)
                    && rule.when.subject.matches(&r.subject)
                    && rule.when.context.matches(&r.context);
                assert_eq!(rule.when.matches(&r), before, "{rule:?} {r:?}");
                assert_eq!(rule.applies(&r), before, "{rule:?} {r:?}");
                count += 1;
            }
        }
    });
    assert!(count > 100_000, "domain too small: {count}");
}

/// An `auth` constraint added to an Allow rule only removes grants (docs/48
/// §7.2 option (i); docs/11 P2): with `auth = c` on every Allow rule of a
/// policy, the decision is unchanged where `c` matches the request and Deny
/// where it does not. Both outcomes occur for inputs the unconstrained
/// policy allows, so the check is not vacuous.
#[test]
fn auth_constraint_only_narrows_an_allow() {
    let constrain = |pol: &PolicySnapshot, c: AuthMatch| {
        let rules = pol
            .rules()
            .iter()
            .cloned()
            .map(|mut r| {
                if r.effect == Effect::Allow {
                    r.when.auth = c;
                }
                r
            })
            .collect();
        policy(rules)
    };
    let (mut kept, mut narrowed) = (0usize, 0usize);
    for_each_equivalence_input(|req, pol, pip| {
        for armored in [true, false] {
            let r = with_armored(req, armored);
            let before = decide(&r, pol, pip);
            for c in [AuthMatch::ARMORED, AuthMatch::UNARMORED] {
                let after = decide(&r, &constrain(pol, c), pip);
                if c.matches(&r.subject.auth) {
                    assert_eq!(after, before, "{c:?} {r:?}");
                } else {
                    assert_eq!(after.effect, Effect::Deny, "{c:?} {r:?}");
                }
                if before.effect == Effect::Allow {
                    if after.effect == Effect::Allow {
                        kept += 1;
                    } else {
                        narrowed += 1;
                    }
                }
            }
        }
    });
    assert!(kept > 0 && narrowed > 0, "{kept} {narrowed}");
}

/// `NotMemberOf(s)` is the exact complement of `MemberOf(s)` (docs/48 §7.2
/// option (ii)): over three principals, every subset of three groups and
/// five SIDs. Only `NotMemberOf` is negated.
#[test]
fn not_member_of_is_the_exact_complement_of_member_of() {
    let sids = [user(), other_user(), group(), other_group(), everyone()];
    let pool = [group(), other_group(), everyone()];
    for principal in [user(), other_user(), group()] {
        for bits in 0u8..8 {
            let groups: Vec<Sid> = pool
                .iter()
                .enumerate()
                .filter(|(i, _)| bits & (1 << i) != 0)
                .map(|(_, s)| *s)
                .collect();
            let s = subject(principal, &groups, Tier::Tier1);
            for sid in sids {
                let member = SubjectMatch::MemberOf(sid).matches(&s);
                assert_eq!(member, is_in(&s, &sid));
                assert_eq!(SubjectMatch::NotMemberOf(sid).matches(&s), !member);
                assert!(SubjectMatch::NotMemberOf(sid).is_negated());
                assert!(!SubjectMatch::MemberOf(sid).is_negated());
            }
        }
    }
}

/// A Deny with `NotMemberOf(g)` denies exactly the complement of `g`
/// (docs/48 §7.2 option (ii); docs/11 §3, P4): appended to any policy of
/// both domains it leaves every decision for a member of `g` unchanged and
/// makes every decision for a non-member Deny — by this rule whenever the
/// policy alone allowed.
#[test]
fn deny_not_member_of_denies_exactly_the_complement() {
    let deny_outside = Rule {
        id: RuleId(77),
        effect: Effect::Deny,
        when: Match {
            subject: SubjectMatch::NotMemberOf(group()),
            ..match_all()
        },
        obligations: vec![],
    };
    let (mut members, mut refused) = (0usize, 0usize);
    for_each_equivalence_input(|req, pol, pip| {
        let mut rules = pol.rules().to_vec();
        rules.push(deny_outside.clone());
        let before = decide(req, pol, pip);
        let after = decide(req, &policy(rules), pip);
        if is_in(&req.subject, &group()) {
            assert_eq!(after, before, "member: {req:?}");
            members += 1;
        } else {
            assert_eq!(after.effect, Effect::Deny, "non-member: {req:?}");
            if before.effect == Effect::Allow {
                assert_eq!(after.reason, ReasonCode::CoarseDeny(RuleId(77)));
                refused += 1;
            }
        }
    });
    assert!(members > 0 && refused > 0, "{members} {refused}");
}

/// A negated subject predicate in an Allow rule grants nothing (Q-130; fail
/// closed): appended to any policy of both domains, an Allow with
/// `NotMemberOf` — carrying an obligation that would show if it applied —
/// leaves every decision unchanged, for members and non-members alike.
#[test]
fn negated_subject_in_an_allow_changes_nothing() {
    for_each_equivalence_input(|req, pol, pip| {
        let before = decide(req, pol, pip);
        for sid in [group(), other_group()] {
            let mut rules = pol.rules().to_vec();
            rules.push(Rule {
                id: RuleId(78),
                effect: Effect::Allow,
                when: Match {
                    subject: SubjectMatch::NotMemberOf(sid),
                    ..match_all()
                },
                obligations: vec![Obligation::Constrain(pdp::Constraint::MaxPageSize(1))],
            });
            assert_eq!(decide(req, &policy(rules), pip), before, "{req:?}");
        }
    });
}

/// The mandatory-FAST set never widens a policy and its Deny rules hold
/// against any Allow (docs/48 §7.2 option (ii); Q-127 interim; P4). Over
/// both domains and both values of `armored`, with `group()` as the
/// bootstrap group:
/// - after appending its two Deny rules, every Allow was the same decision
///   before;
/// - an unarmored Kerberos request is then denied unless it is an AS by a
///   member of the bootstrap group — also under the Allow-everything and
///   Allow-Kerberos policies of the domain;
/// - the full set (Deny and Allow rules) changes no non-Kerberos decision.
#[test]
fn mandatory_fast_never_widens_a_policy() {
    let full = mandatory_fast_rules(group(), RuleId(100)).expect("ids fit");
    let denies: Vec<Rule> = full
        .iter()
        .filter(|r| r.effect == Effect::Deny)
        .cloned()
        .collect();
    assert_eq!(denies.len(), 2);
    let mut refused_downgrades = 0usize;
    for_each_equivalence_input(|req, pol, pip| {
        for armored in [true, false] {
            let r = with_armored(req, armored);
            let before = decide(&r, pol, pip);
            let mut with_denies = pol.rules().to_vec();
            with_denies.extend(denies.iter().cloned());
            let after = decide(&r, &policy(with_denies), pip);
            if after.effect == Effect::Allow {
                assert_eq!(after, before, "widened: {r:?}");
            }
            let kerberos = r.action.class() == ActionClass::Kerberos;
            if !kerberos {
                let mut with_full = pol.rules().to_vec();
                with_full.extend(full.iter().cloned());
                assert_eq!(decide(&r, &policy(with_full), pip), before, "{r:?}");
            }
            let bootstrap_as = r.action == Action::KdcAs && is_in(&r.subject, &group());
            if kerberos && !armored && !bootstrap_as {
                assert_eq!(after.effect, Effect::Deny, "downgrade: {r:?}");
                if before.effect == Effect::Allow {
                    refused_downgrades += 1;
                }
            }
        }
    });
    assert!(refused_downgrades > 0);
}

/// The mandatory-FAST set alone, exactly (docs/48 §7.1-§7.3; Q-127 interim
/// (1), (4)), with P1 / P7 / P2 over the Kerberos domain and both values of
/// `armored`: the decision is deterministic, carries one Audit, and is
/// Allow exactly when the request is well formed, authenticated, its tier
/// agrees with the PIP, and either it is armored and an AS or TGS, or it is
/// unarmored and an AS for a TGT by a member of the bootstrap group.
#[test]
fn mandatory_fast_set_alone_is_exact() {
    use pdp::{KerbResKind, Resource};
    let bootstrap = group();
    let snapshot = policy(mandatory_fast_rules(bootstrap, RuleId(100)).expect("ids fit"));
    let mut allowed = 0usize;
    for pip_tier in [Tier::Tier0, Tier::Tier1] {
        let mut pip = MockPip::with_sd(sd(None, vec![]));
        pip.tiers.insert(user(), pip_tier);
        for s in subjects() {
            for (action, resource) in kerberos_cases() {
                for armored in [true, false] {
                    let req = with_armored(
                        &AccessRequest {
                            subject: s.clone(),
                            resource: resource.clone(),
                            action: action.clone(),
                            context: strong_context(),
                        },
                        armored,
                    );
                    let d = decide(&req, &snapshot, &pip);
                    assert_eq!(d, decide(&req, &snapshot, &pip), "P1");
                    assert!(exactly_one_audit(&d), "P7: {d:?}");
                    assert_eq!(d.effect == Effect::Allow, d.reason == ReasonCode::Allowed);
                    if d.effect == Effect::Allow {
                        assert!(
                            snapshot
                                .rules()
                                .iter()
                                .any(|r| r.effect == Effect::Allow && r.applies(&req)),
                            "P2"
                        );
                    }
                    let well_formed = matches!(resource, Resource::Kerberos { .. });
                    let authenticated =
                        s.auth.strength != AuthStrength::Unauth && s.auth.ticket_verified;
                    let tier_ok = s.tier == pip_tier;
                    let is_tgt = matches!(
                        resource,
                        Resource::Kerberos {
                            kind: KerbResKind::Tgt
                        }
                    );
                    let grant = if armored {
                        matches!(action, Action::KdcAs | Action::KdcTgs)
                    } else {
                        action == Action::KdcAs && is_tgt && is_in(&s, &bootstrap)
                    };
                    let expected = well_formed && authenticated && tier_ok && grant;
                    assert_eq!(d.effect == Effect::Allow, expected, "{req:?}: {d:?}");
                    allowed += usize::from(expected);
                }
            }
        }
    }
    assert!(allowed > 0);
}

// ------------------------------- LDAP extensions: never widen (Q-164) ----
//
// Source: Q-164 items 1-3 (A-48); Q-170 item 3 (A-51); docs/49 §5.2
// (R49-10); docs/15 §6; [MS-ADTS] v20261026 3.1.1.3, 3.1.1.4.4; [MS-DTYP]
// 2.5.3.2; docs/11 §3-§4, §10. Hand-made domains; no vector from another
// implementation.
//
// The two fixes and the source-network constraint only narrow, and the new
// resource changes no other decision:
// - `accepted_subtree_rules_never_match_outside_their_base` — the empty-base
//   fix (the only base that matched outside itself can no longer be built);
// - `nt_security_descriptor_fix_only_narrows` — against the pre-fix PDP,
//   reproduced by renaming the attribute (no other code path knows it);
// - `source_network_fix_only_narrows` — against the pre-fix allowlist,
//   reproduced by the same request from the internal network (the pre-fix
//   allowlist had no network; an external entry can no longer be built);
// - `accepted_anonymous_grants_never_admit_the_external_network` — A-51:
//   External is refused in `AnonymousGrant::new`, and no accepted entry,
//   alone or together with the others, admits an anonymous request from
//   the external network;
// - `root_dse_changes_no_other_decision` — over the equivalence domain;
// - `root_dse_requests_keep_the_invariants` — P1-P4, P7, P9 and the exact
//   outcome of every rootDSE request.
//
// One-time differential check against the pre-change build (the commit
// before this change), over a hand-made domain of 5,760 inputs (3 subjects ×
// 8 directory requests, including an nTSecurityDescriptor read and the
// empty DN × 2 networks × 3 transports × 5 descriptors × 8 policies,
// including rules and allowlist entries over the empty subtree and an entry
// over every resource): each pre-change policy was mapped through the fix —
// a policy holding a refused item builds no snapshot (every decision Deny),
// every other allowlist entry names the internal network. Result: 332
// decisions went from Allow to Deny, none from Deny to Allow; on the
// policies that still build, the only changes were the
// nTSecurityDescriptor read, the empty-DN directory object, and anonymous
// requests from the external network.

/// Every DN of up to `max` components over `alphabet`, the empty DN first.
fn all_dns(alphabet: &[&str], max: usize) -> Vec<Dn> {
    let mut out: Vec<Vec<String>> = vec![Vec::new()];
    let mut layer: Vec<Vec<String>> = vec![Vec::new()];
    for _ in 0..max {
        let mut next = Vec::new();
        for dn in &layer {
            for component in alphabet {
                let mut longer = dn.clone();
                longer.push((*component).to_string());
                next.push(longer);
            }
        }
        out.extend(next.iter().cloned());
        layer = next;
    }
    out.into_iter().map(Dn::new).collect()
}

/// "`dn` is `base` or lies below it", stated independently of the crate:
/// the last `base.len()` components of `dn` are `base`'s, in order.
fn within(dn: &Dn, base: &Dn) -> bool {
    let (d, b) = (dn.rdns(), base.rdns());
    d.len() >= b.len() && d[d.len() - b.len()..] == *b
}

/// Q-164 item 2 (A-48): over every DN of up to four components (341 DNs,
/// with the empty one) as base and as object: the empty base is refused,
/// every other base is accepted, and an accepted subtree matches a
/// directory object exactly when the object is the base or below it —
/// never outside it, never the rootDSE. Through `decide`, an Allow rule and
/// a Deny rule over an accepted subtree (DNs of up to three components)
/// apply exactly inside it.
#[test]
fn accepted_subtree_rules_never_match_outside_their_base() {
    let alphabet = ["dc=test", "ou=unit", "cn=a", "ou=other"];
    let dns = all_dns(&alphabet, 4);
    assert_eq!(dns.len(), 341);
    let mut matched = 0usize;
    for base in &dns {
        let accepted = SubtreeBase::new(base.clone());
        if base.rdns().is_empty() {
            assert_eq!(accepted, Err(RuleError::EmptySubtreeBase));
            continue;
        }
        let base_match = ResourceMatch::DirSubtree {
            base: accepted.expect("non-empty base"),
        };
        assert!(!base_match.matches(&Resource::RootDse));
        for dn in &dns {
            for attr in [None, Some(AttrId(attr_alone()))] {
                let m = base_match.matches(&Resource::DirObject {
                    dn: dn.clone(),
                    attr,
                });
                assert_eq!(m, within(dn, base), "{base:?} {dn:?}");
                assert!(!m || !dn.rdns().is_empty(), "{base:?} matched the empty DN");
                matched += usize::from(m);
            }
        }
    }
    assert!(matched > 0);

    // Through decide.
    let small = all_dns(&alphabet, 3);
    let mut pip = MockPip::with_sd(sd(None, vec![]));
    for dn in &small {
        pip.sds.insert(
            dn.clone(),
            sd(None, vec![allow(RIGHT_GENERIC_ALL, group())]),
        );
    }
    let (mut inside, mut outside) = (0usize, 0usize);
    for base in small.iter().filter(|b| !b.rdns().is_empty()) {
        let allow_rule = Rule {
            id: RuleId(1),
            effect: Effect::Allow,
            when: Match {
                resource: subtree(base.clone()),
                ..match_all()
            },
            obligations: vec![],
        };
        let deny_rule = Rule {
            id: RuleId(2),
            effect: Effect::Deny,
            ..allow_rule.clone()
        };
        let allow_in = policy(vec![allow_rule]);
        let deny_in = policy(vec![allow_everything(1), deny_rule]);
        for dn in small.iter().filter(|d| !d.rdns().is_empty()) {
            let mut req = dir_request(the_user(), Action::DirRead, None);
            req.resource = Resource::DirObject {
                dn: dn.clone(),
                attr: None,
            };
            let w = within(dn, base);
            assert_eq!(decide(&req, &allow_in, &pip).effect == Effect::Allow, w);
            assert_eq!(
                decide(&req, &deny_in, &pip).reason == ReasonCode::CoarseDeny(RuleId(2)),
                w
            );
            if w {
                inside += 1;
            } else {
                outside += 1;
            }
        }
    }
    assert!(inside > 0 && outside > 0);
}

/// The GUID that stands for nTSecurityDescriptor in the pre-fix
/// reproduction: used nowhere else in these domains.
fn renamed_ntsd() -> Guid {
    guid(0x7E)
}

fn rename_guid(g: Guid) -> Guid {
    if g == AttrId::NT_SECURITY_DESCRIPTOR.0 {
        renamed_ntsd()
    } else {
        g
    }
}

fn rename_ace(ace: &Ace) -> Ace {
    match ace {
        Ace::AccessAllowedObject(o) => {
            let mut o = o.clone();
            o.object_type = o.object_type.map(rename_guid);
            Ace::AccessAllowedObject(o)
        }
        Ace::AccessDeniedObject(o) => {
            let mut o = o.clone();
            o.object_type = o.object_type.map(rename_guid);
            Ace::AccessDeniedObject(o)
        }
        other => other.clone(),
    }
}

/// [MS-ADTS] 3.1.1.4.4 fix (Q-164, A-48) only narrows. The pre-fix PDP
/// treated nTSecurityDescriptor as an opaque GUID like any other; renaming
/// it consistently (request, object ACEs, PIP tables) to a GUID nothing
/// else uses therefore reproduces the pre-fix decision with the current
/// code. Over every DACL of up to two ACEs (simple and object ACEs naming
/// the attribute, with RP, RC, RP|RC and GENERIC_ALL, allow and deny, two
/// trustees), two owners, two attribute classes and four requests: a read
/// of nTSecurityDescriptor is always Deny now, and every other decision is
/// identical to the pre-fix one — so every change is Allow → Deny (or a
/// Deny reason). The domain reaches pre-fix Allows of the read, so the
/// check is not vacuous.
#[test]
fn nt_security_descriptor_fix_only_narrows() {
    let ntsd = AttrId::NT_SECURITY_DESCRIPTOR;
    let mut alphabet = Vec::new();
    for sid in [user(), other_user()] {
        for mask in [
            RIGHT_DS_READ_PROPERTY,
            RIGHT_READ_CONTROL,
            RIGHT_DS_READ_PROPERTY | RIGHT_READ_CONTROL,
            RIGHT_GENERIC_ALL,
        ] {
            alphabet.push(allow(mask, sid));
            alphabet.push(deny(mask, sid));
            alphabet.push(allow_obj(mask, Some(ntsd.0), sid));
            alphabet.push(deny_obj(mask, Some(ntsd.0), sid));
            alphabet.push(allow_obj(mask, Some(attr_alone()), sid));
        }
    }
    let mut dacls: Vec<Vec<Ace>> = vec![vec![]];
    dacls.extend(alphabet.iter().map(|a| vec![a.clone()]));
    for a in &alphabet {
        for b in &alphabet {
            dacls.push(vec![a.clone(), b.clone()]);
        }
    }
    let requests = [
        (Action::DirRead, Some(ntsd.0)),
        (Action::DirWrite, Some(ntsd.0)),
        (Action::DirRead, Some(attr_alone())),
        (Action::DirRead, None),
    ];
    let pol = policy(vec![allow_everything(1)]);
    let (mut narrowed, mut checked) = (0usize, 0usize);
    for aces in &dacls {
        for owner in [None, Some(user())] {
            for class in [AttrClass::Normal, AttrClass::Secret] {
                let mut now_pip = MockPip::with_sd(sd(owner, aces.clone()));
                now_pip.attr_classes.insert(ntsd, class);
                let mut before_pip =
                    MockPip::with_sd(sd(owner, aces.iter().map(rename_ace).collect()));
                before_pip
                    .attr_classes
                    .insert(AttrId(renamed_ntsd()), class);
                for (action, attr) in &requests {
                    let now_req = dir_request(the_user(), action.clone(), *attr);
                    let before_req = dir_request(the_user(), action.clone(), attr.map(rename_guid));
                    let now = decide(&now_req, &pol, &now_pip);
                    let before = decide(&before_req, &pol, &before_pip);
                    if *action == Action::DirRead && *attr == Some(ntsd.0) {
                        assert_eq!(now.effect, Effect::Deny, "{aces:?} {owner:?}");
                        if before.effect == Effect::Allow {
                            narrowed += 1;
                        }
                    } else {
                        assert_eq!(now, before, "{action:?} {attr:?} {aces:?} {owner:?}");
                    }
                    checked += 1;
                }
            }
        }
    }
    assert!(checked > 20_000, "domain too small: {checked}");
    assert!(narrowed > 0, "the domain never reached a pre-fix Allow");
}

const ENC_ONLY: TransportSec = TransportSec {
    encrypted: true,
    sealed: false,
    channel_bound: false,
};
const ALL_SEC: TransportSec = TransportSec {
    encrypted: true,
    sealed: true,
    channel_bound: true,
};

/// The allowlist entries of the source-network check, as the pre-fix
/// allowlist held them: (action, resource, transport minimum), no network.
fn networkless_entries() -> Vec<(ActionMatch, ResourceMatch, TransportSec)> {
    vec![
        (
            ActionMatch::Exact(Action::DirRead),
            ResourceMatch::RootDse,
            TransportSec::NONE,
        ),
        (
            ActionMatch::Exact(Action::DirRead),
            subtree(parent_dn()),
            TransportSec::NONE,
        ),
        (
            ActionMatch::AnyOf(vec![Action::DirRead, Action::DirList]),
            subtree(parent_dn()),
            ENC_ONLY,
        ),
        (
            ActionMatch::Class(ActionClass::Directory),
            subtree(obj_dn()),
            ALL_SEC,
        ),
        (
            ActionMatch::Exact(Action::DirRead),
            subtree(parent_dn()),
            ALL_SEC,
        ),
    ]
}

/// The allowlist with each pre-fix entry mapped to the internal network —
/// the only network an entry can name (docs/15 §6; A-51).
fn internal_entries(picked: &[(ActionMatch, ResourceMatch, TransportSec)]) -> Vec<AnonymousGrant> {
    picked
        .iter()
        .map(|(action, resource, min)| {
            AnonymousGrant::new(action.clone(), resource.clone(), *min, IpScope::Internal)
                .expect("bounded, internal")
        })
        .collect()
}

/// docs/15 §6 / Q-164 item 3 / A-51 only narrows. The pre-fix allowlist had
/// no network: its entries matched on action and resource alone. With each
/// pre-fix entry mapped to the internal network, a request from the
/// internal network meets exactly the entries the pre-fix allowlist would
/// have matched; every rule here leaves `src_net` open (checked), and
/// nothing else in `decide` reads the network. So the pre-fix decision for
/// a request from EITHER network is the decision for the same request from
/// the internal network under the mapped allowlist. (Before A-51 this was
/// reproduced by one entry per network; an external entry can no longer be
/// built.) From the external network every anonymous request is denied and
/// authenticated ones are unchanged, so every change is Allow → Deny. Over
/// seven allowlists (including joined minimums), authenticated and
/// anonymous subjects, six requests (the rootDSE among them), three
/// transports and two policies.
#[test]
fn source_network_fix_only_narrows() {
    let entries = networkless_entries();
    let pick = |idx: &[usize]| -> Vec<(ActionMatch, ResourceMatch, TransportSec)> {
        idx.iter()
            .filter_map(|i| entries.get(*i).cloned())
            .collect()
    };
    let allowlists = [
        pick(&[]),
        pick(&[0]),
        pick(&[1]),
        pick(&[2]),
        pick(&[1, 4]),
        pick(&[0, 3]),
        pick(&[0, 1, 2, 3, 4]),
    ];
    let other_dn = Dn::new(vec!["cn=x".into(), "ou=other".into(), "dc=test".into()]);
    let mut pip = MockPip::with_sd(sd(
        None,
        vec![
            allow(RIGHT_GENERIC_ALL, everyone()),
            allow(RIGHT_GENERIC_ALL, group()),
        ],
    ));
    for dn in [parent_dn(), other_dn.clone()] {
        pip.sds.insert(
            dn,
            sd(
                None,
                vec![
                    allow(RIGHT_GENERIC_ALL, everyone()),
                    allow(RIGHT_GENERIC_ALL, group()),
                ],
            ),
        );
    }
    let dir = |dn: Dn, attr: Option<Guid>| Resource::DirObject {
        dn,
        attr: attr.map(AttrId),
    };
    let requests = [
        (Action::DirRead, dir(obj_dn(), None)),
        (Action::DirRead, dir(obj_dn(), Some(attr_alone()))),
        (Action::DirList, dir(obj_dn(), None)),
        (Action::DirWrite, dir(obj_dn(), Some(attr_alone()))),
        (Action::DirRead, dir(other_dn, None)),
        (Action::DirRead, Resource::RootDse),
    ];
    let mut anonymous = subject(everyone(), &[], Tier::Tier1);
    anonymous.auth.strength = AuthStrength::Unauth;
    anonymous.auth.ticket_verified = false;
    let rule_sets = [
        vec![allow_everything(1)],
        vec![
            Rule {
                id: RuleId(1),
                effect: Effect::Allow,
                when: Match {
                    resource: ResourceMatch::RootDse,
                    ..match_all()
                },
                obligations: vec![],
            },
            Rule {
                id: RuleId(2),
                effect: Effect::Allow,
                when: Match {
                    resource: subtree(parent_dn()),
                    ..match_all()
                },
                obligations: vec![],
            },
        ],
    ];
    // The premise of the reproduction: no rule constrains the network.
    for rules in &rule_sets {
        assert!(rules.iter().all(|r| r.when.context.src_net.is_none()));
    }
    let (mut narrowed, mut kept) = (0usize, 0usize);
    for picked in &allowlists {
        for rules in &rule_sets {
            let internal =
                PolicySnapshot::new(PolicyVersion(1), rules.clone(), internal_entries(picked));
            for s in [the_user(), anonymous.clone()] {
                let authenticated = s.auth.strength != AuthStrength::Unauth;
                for (action, resource) in &requests {
                    for sec in [TransportSec::NONE, ENC_ONLY, ALL_SEC] {
                        let at = |net: IpScope| {
                            let mut req = AccessRequest {
                                subject: s.clone(),
                                resource: resource.clone(),
                                action: action.clone(),
                                context: strong_context(),
                            };
                            req.context.transport_sec = sec;
                            req.context.src_net = net;
                            req
                        };
                        let (int_req, ext_req) = (at(IpScope::Internal), at(IpScope::External));
                        // The pre-fix decision, for either network (see
                        // the test documentation).
                        let before_ext = decide(&int_req, &internal, &pip);
                        // From the external network.
                        let now_ext = decide(&ext_req, &internal, &pip);
                        if authenticated {
                            assert_eq!(now_ext, before_ext);
                        } else {
                            assert_eq!(now_ext.effect, Effect::Deny, "{ext_req:?}");
                            if before_ext.effect == Effect::Allow {
                                narrowed += 1;
                            }
                        }
                        if now_ext.effect == Effect::Allow {
                            assert_eq!(now_ext, before_ext);
                            kept += 1;
                        }
                    }
                }
            }
        }
    }
    assert!(narrowed > 0 && kept > 0, "{narrowed} {kept}");
}

/// docs/15 §6 ("only these, from the internal network"); A-51 (Q-170 item
/// 3): never widen. Over every candidate allowlist entry of the domain
/// (seven action matchers × eight resource matchers, `Any` among them ×
/// three transport minimums × both networks): construction accepts exactly
/// the bounded internal entries, refuses every external one, and every
/// accepted entry names the internal network. No accepted entry matches a
/// request from the external network — over two unauthenticated subjects,
/// seven actions × seven resources and three transports — and through
/// `decide`, under the widest rules (Allow everything), neither any single
/// accepted entry nor all of them together let an anonymous request from
/// the external network past layer 1: each is denied as malformed or
/// unauthenticated, exactly as with no allowlist at all. The same entries do
/// admit requests from the internal network (the domain is not vacuous).
#[test]
fn accepted_anonymous_grants_never_admit_the_external_network() {
    let actions = [
        ActionMatch::Any,
        ActionMatch::Exact(Action::DirRead),
        ActionMatch::Exact(Action::DirList),
        ActionMatch::AnyOf(vec![Action::DirRead, Action::DirList]),
        ActionMatch::Class(ActionClass::Directory),
        ActionMatch::Class(ActionClass::Dns),
        ActionMatch::Class(ActionClass::Kerberos),
    ];
    let zone = || pdp::ZoneId("test".into());
    let resources = [
        ResourceMatch::Any,
        ResourceMatch::RootDse,
        subtree(parent_dn()),
        subtree(obj_dn()),
        ResourceMatch::Dns { zone: zone() },
        ResourceMatch::Kerberos { kind: None },
        ResourceMatch::Kerberos {
            kind: Some(pdp::KerbResKind::Tgt),
        },
        ResourceMatch::Policy { scope: None },
    ];
    let mut accepted = Vec::new();
    let mut candidates = 0usize;
    for action in &actions {
        for resource in &resources {
            for min in [TransportSec::NONE, ENC_ONLY, ALL_SEC] {
                for net in [IpScope::Internal, IpScope::External] {
                    let built = AnonymousGrant::new(action.clone(), resource.clone(), min, net);
                    // The resource is checked before the network.
                    let refusal = if matches!(resource, ResourceMatch::Any) {
                        Some(RuleError::UnboundedAnonymousResource)
                    } else if net == IpScope::External {
                        Some(RuleError::AnonymousExternalNetwork)
                    } else {
                        None
                    };
                    assert_eq!(
                        built.as_ref().err().copied(),
                        refusal,
                        "{action:?} {resource:?} {net:?}"
                    );
                    if let Ok(g) = built {
                        assert_eq!(g.src_net(), IpScope::Internal);
                        accepted.push(g);
                    }
                    candidates += 1;
                }
            }
        }
    }
    assert_eq!(candidates, 7 * 8 * 3 * 2);
    assert_eq!(accepted.len(), 7 * 7 * 3);

    let mut unverified = subject(everyone(), &[], Tier::Tier1);
    unverified.auth.ticket_verified = false;
    let mut anonymous = unverified.clone();
    anonymous.auth.strength = AuthStrength::Unauth;
    let request_actions = [
        Action::DirRead,
        Action::DirList,
        Action::DirWrite,
        Action::DnsUpdate,
        Action::KdcAs,
        Action::KdcTgs,
        Action::PolicyAdmin,
    ];
    let request_resources = [
        Resource::RootDse,
        Resource::DirObject {
            dn: obj_dn(),
            attr: None,
        },
        Resource::DirObject {
            dn: obj_dn(),
            attr: Some(AttrId(attr_alone())),
        },
        Resource::DirObject {
            dn: parent_dn(),
            attr: None,
        },
        Resource::Dns {
            zone: zone(),
            record: None,
        },
        Resource::Kerberos {
            kind: pdp::KerbResKind::Tgt,
        },
        Resource::Policy {
            scope: pdp::PolicyScope("domain".into()),
        },
    ];
    let mut requests = Vec::new();
    for s in [anonymous, unverified] {
        for action in &request_actions {
            for resource in &request_resources {
                for sec in transports() {
                    let mut req = AccessRequest {
                        subject: s.clone(),
                        resource: resource.clone(),
                        action: action.clone(),
                        context: strong_context(),
                    };
                    req.context.transport_sec = sec;
                    requests.push(req);
                }
            }
        }
    }
    let at = |req: &AccessRequest, net: IpScope| {
        let mut r = req.clone();
        r.context.src_net = net;
        r
    };

    // The matcher itself.
    let mut internal_matches = 0usize;
    for g in &accepted {
        for req in &requests {
            assert!(!g.matches(&at(req, IpScope::External)), "{g:?} {req:?}");
            internal_matches += usize::from(g.matches(&at(req, IpScope::Internal)));
        }
    }
    assert!(internal_matches > 0);

    // Through decide.
    let pip = MockPip::with_sd(sd(None, vec![allow(RIGHT_GENERIC_ALL, everyone())]));
    let rules = vec![allow_everything(1)];
    let no_allowlist = policy(rules.clone());
    let mut allowlists: Vec<Vec<AnonymousGrant>> =
        accepted.iter().map(|g| vec![g.clone()]).collect();
    allowlists.push(accepted.clone());
    let mut internal_allowed = 0usize;
    for req in &requests {
        let (int_req, ext_req) = (at(req, IpScope::Internal), at(req, IpScope::External));
        let without = decide(&ext_req, &no_allowlist, &pip);
        assert_eq!(without.effect, Effect::Deny);
        assert!(
            matches!(
                without.reason,
                ReasonCode::InvalidRequest | ReasonCode::Unauthenticated
            ),
            "{without:?}"
        );
        for entries in &allowlists {
            let pol = PolicySnapshot::new(PolicyVersion(1), rules.clone(), entries.clone());
            assert_eq!(
                decide(&ext_req, &pol, &pip),
                without,
                "{ext_req:?} {entries:?}"
            );
            internal_allowed += usize::from(decide(&int_req, &pol, &pip).effect == Effect::Allow);
        }
    }
    assert!(internal_allowed > 0);
}

/// docs/49 §5.2 (R49-10): the new resource changes no other decision. Over
/// the whole equivalence domain (directory and Kerberos inputs, 142,776),
/// appending an Allow rule on the rootDSE, a Deny rule on the rootDSE, or
/// an anonymous-allowlist entry for the rootDSE (internal network — an
/// external entry cannot be built, A-51) to any policy of the domain leaves
/// every decision identical.
#[test]
fn root_dse_changes_no_other_decision() {
    let root_rule = |id: u32, effect: Effect| Rule {
        id: RuleId(id),
        effect,
        when: Match {
            resource: ResourceMatch::RootDse,
            ..match_all()
        },
        obligations: vec![Obligation::Constrain(pdp::Constraint::MaxPageSize(1))],
    };
    let root_entries = vec![AnonymousGrant::new(
        ActionMatch::Any,
        ResourceMatch::RootDse,
        TransportSec::NONE,
        IpScope::Internal,
    )
    .expect("bounded")];
    assert_eq!(
        AnonymousGrant::new(
            ActionMatch::Any,
            ResourceMatch::RootDse,
            TransportSec::NONE,
            IpScope::External,
        ),
        Err(RuleError::AnonymousExternalNetwork)
    );
    let mut count = 0usize;
    for_each_equivalence_input(|req, pol, pip| {
        let before = decide(req, pol, pip);
        for effect in [Effect::Allow, Effect::Deny] {
            let mut rules = pol.rules().to_vec();
            rules.push(root_rule(90, effect));
            assert_eq!(
                decide(req, &policy(rules), pip),
                before,
                "{effect:?} {req:?}"
            );
        }
        let with_entries =
            PolicySnapshot::new(pol.version(), pol.rules().to_vec(), root_entries.clone());
        assert_eq!(decide(req, &with_entries, pip), before, "{req:?}");
        count += 1;
    });
    assert_eq!(count, EQUIVALENCE_DOMAIN);
}

/// P1-P4, P7, P9 for rootDSE requests, and their exact outcome (docs/11 §4,
/// §10; docs/49 §5.2; docs/15 §6; Q-164 items 1, 3; A-51). Over twelve
/// subjects, every directory action and two others on the rootDSE, both
/// networks, three transports, five rule sets, four allowlists (internal
/// entries only, A-51) and both PIP tiers:
/// deterministic with one Audit, Allow ⇔ reason Allowed; an Allow needs an
/// applying Allow rule (P2); a tier disagreeing with the PIP denies (P3); a
/// Deny-everything rule denies (P4); `Context.time` changes nothing (P9);
/// and Allow holds exactly when the action is `DirRead`, the tier agrees,
/// the subject is authenticated over the read floor or anonymous with an
/// entry for its network whose minimums the transport meets, an Allow rule
/// matches the rootDSE and no Deny rule does.
#[test]
fn root_dse_requests_keep_the_invariants() {
    let rule = |id: u32, effect: Effect, resource: ResourceMatch| Rule {
        id: RuleId(id),
        effect,
        when: Match {
            resource,
            ..match_all()
        },
        obligations: vec![],
    };
    let rule_sets: Vec<Vec<Rule>> = vec![
        vec![],
        vec![allow_everything(1)],
        vec![rule(1, Effect::Allow, ResourceMatch::RootDse)],
        vec![
            allow_everything(1),
            rule(2, Effect::Deny, ResourceMatch::RootDse),
        ],
        vec![rule(1, Effect::Allow, subtree(parent_dn()))],
    ];
    let entry = |net: IpScope, min: TransportSec| {
        AnonymousGrant::new(
            ActionMatch::Exact(Action::DirRead),
            ResourceMatch::RootDse,
            min,
            net,
        )
        .expect("bounded")
    };
    // Every entry names the internal network: an external one cannot be
    // built (A-51), so anonymous requests from the external network meet no
    // entry. The last allowlist joins two minimums.
    let allowlists = vec![
        vec![],
        vec![entry(IpScope::Internal, TransportSec::NONE)],
        vec![entry(IpScope::Internal, ENC_ONLY)],
        vec![
            entry(IpScope::Internal, TransportSec::NONE),
            entry(IpScope::Internal, ALL_SEC),
        ],
    ];
    let actions = [
        Action::DirRead,
        Action::DirWrite,
        Action::DirList,
        Action::DirDelete,
        Action::DirAddChild(ObjClass(class_group())),
        Action::DirControlRight(ControlRightId(right_a())),
        Action::RpcCall,
        Action::KdcAs,
    ];
    let deny_all = Rule {
        id: RuleId(99),
        effect: Effect::Deny,
        when: match_all(),
        obligations: vec![],
    };
    let (mut allowed, mut total) = (0usize, 0usize);
    for pip_tier in [Tier::Tier0, Tier::Tier1] {
        let mut pip = MockPip::with_sd(sd(None, vec![]));
        pip.tiers.insert(user(), pip_tier);
        for s in subjects() {
            for action in &actions {
                for net in [IpScope::Internal, IpScope::External] {
                    for sec in transports() {
                        let mut req = AccessRequest {
                            subject: s.clone(),
                            resource: Resource::RootDse,
                            action: action.clone(),
                            context: strong_context(),
                        };
                        req.context.src_net = net;
                        req.context.transport_sec = sec;
                        for rules in &rule_sets {
                            for entries in &allowlists {
                                let pol = PolicySnapshot::new(
                                    PolicyVersion(1),
                                    rules.clone(),
                                    entries.clone(),
                                );
                                let d = decide(&req, &pol, &pip);
                                assert_eq!(d, decide(&req, &pol, &pip), "P1");
                                assert!(exactly_one_audit(&d), "P7: {d:?}");
                                assert_eq!(
                                    d.effect == Effect::Allow,
                                    d.reason == ReasonCode::Allowed
                                );
                                if d.effect == Effect::Allow {
                                    assert!(
                                        rules
                                            .iter()
                                            .any(|r| r.effect == Effect::Allow && r.applies(&req)),
                                        "P2"
                                    );
                                }
                                if s.tier != pip_tier {
                                    assert_eq!(d.effect, Effect::Deny, "P3");
                                }
                                let mut with_deny = rules.clone();
                                with_deny.push(deny_all.clone());
                                let denied = PolicySnapshot::new(
                                    PolicyVersion(1),
                                    with_deny,
                                    entries.clone(),
                                );
                                assert_eq!(decide(&req, &denied, &pip).effect, Effect::Deny, "P4");
                                let mut later = req.clone();
                                later.context.time = Instant(u64::MAX);
                                assert_eq!(decide(&later, &pol, &pip), d, "P9");

                                // The exact outcome, computed independently.
                                let authenticated = s.auth.strength != AuthStrength::Unauth
                                    && s.auth.ticket_verified;
                                let floor = if authenticated {
                                    Some(ENC_ONLY)
                                } else {
                                    entries.iter().filter(|e| e.src_net() == net).fold(
                                        None,
                                        |f: Option<TransportSec>, e| {
                                            Some(
                                                f.unwrap_or(TransportSec::NONE)
                                                    .union(e.min_transport()),
                                            )
                                        },
                                    )
                                };
                                let transport_ok = floor.is_some_and(|f| sec.meets(f));
                                let allow_rule = rules.iter().any(|r| {
                                    r.effect == Effect::Allow
                                        && matches!(
                                            r.when.resource,
                                            ResourceMatch::Any | ResourceMatch::RootDse
                                        )
                                });
                                let deny_rule = rules.iter().any(|r| r.effect == Effect::Deny);
                                let expected = *action == Action::DirRead
                                    && s.tier == pip_tier
                                    && transport_ok
                                    && allow_rule
                                    && !deny_rule;
                                assert_eq!(d.effect == Effect::Allow, expected, "{req:?} {d:?}");
                                allowed += usize::from(expected);
                                total += 1;
                            }
                        }
                    }
                }
            }
        }
    }
    assert!(total > 10_000, "domain too small: {total}");
    assert!(allowed > 0);
}
